void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = fragCoord/iResolution.xy * 2.0 - 1.0;
    uv.x *= iResolution.x / iResolution.y;

    float iT = mod(iTime, 6.0);
    float shiftx = -0.361;
    float shifty = -0.64514;

    uv.x += shiftx;
    uv.y += shifty;

    uv.x *= 1.0/(pow(iT+1.0,iT+1.0));
    uv.x -= shiftx;
    uv.y *= 1.0/(pow(iT+1.0,iT+1.0));
    uv.y -= shifty;

    vec2 f = uv;
    vec3 col = vec3(1.0,1.0,1.0);
    float a = 0.0;
    float num = 0.0;

    for(int i = 0; i < 1000; i++)
    {
        f = vec2(f.x * f.x - f.y * f.y + uv.x, 2.0 * f.x * f.y + uv.y);

        a = f.x * f.x + f.y * f.y;

        if(a <= 4.0)
        {
            col = vec3(a*0.1,a*0.1,0.5);
        }
    }

    a = f.x * f.x + f.y * f.y;

    if(a <= 4.0)
    {
        col = vec3(0.0,0.0,0.0);
    }


    // Output to screen
    fragColor = vec4(col,1.0);
}
